const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Demo Sender',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const d = $input.first().json;
const s = d.signal;

const eligible = s.daysOld <= 14 && !s.contactedRecently;

const angles = {
  new_hiring: "Scaling a team often exposes manual handoffs and inconsistent processes.",
  funding: "New capital creates an ideal window to automate before operational complexity compounds.",
  leadership_change: "New leadership often reviews systems, ownership, and reporting workflows.",
  expansion: "Expansion creates pressure on intake, routing, CRM hygiene, and follow-up."
};

const angle =
  angles[s.type] ||
  "This change may create new workflow and automation priorities.";

const reason = eligible
  ? "Fresh signal and no recent contact"
  : s.contactedRecently
    ? "Contact suppressed because recent outreach already occurred"
    : "Contact suppressed because the trigger is more than 14 days old";

const result = {
  eligible,
  status: eligible ? "ready_for_outreach" : "suppressed",
  trigger: s.type,
  company: s.company,
  contact: {
    firstName: s.firstName,
    role: s.role
  },
  reason,
  subject: null,
  message: null
};

if (eligible) {
  result.subject = `${s.firstName}, a workflow idea for ${s.company}`;
  result.message = `Hi ${s.firstName},

I noticed ${s.company} ${s.detail}. ${angle}

I build focused n8n systems that reduce manual work and improve visibility without forcing a full-stack replacement.

Would a brief workflow review be useful?

Best,
${d.config.senderName}`;
}

return [{ json: { ...d, result } }];
